from AlgorithmImports import *
from collections import deque
from decimal import Decimal
import math


class ParallelSpyAaplStrategy(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        self.tickers = ["SPY", "AAPL", "IBM", "BAC", "AIG"]
        self.symbols = {
            ticker: self.AddEquity(ticker, Resolution.Daily).Symbol
            for ticker in self.tickers
        }

        self.sma_period = 20
        self.spy_closes = deque(maxlen=self.sma_period + 1)
        self.aapl_closes = deque(maxlen=15)

        self.aapl_red_streak = 0
        self.aapl_average_gain = None
        self.aapl_average_loss = None
        self.aapl_rsi = None
        self.aapl_rsi_changes = 0
        self.aapl_seed_gains = []
        self.aapl_seed_losses = []

        self.strategy_a_shares = 0
        self.strategy_b_shares = 0

    def OnData(self, data: Slice):
        if any(not data.Bars.ContainsKey(self.symbols[ticker])
               for ticker in self.tickers):
            return

        spy_close = data.Bars[self.symbols["SPY"]].Close
        aapl_close = data.Bars[self.symbols["AAPL"]].Close

        previous_aapl_close = (
            self.aapl_closes[-1] if self.aapl_closes else None
        )

        if previous_aapl_close is not None:
            if aapl_close < previous_aapl_close:
                self.aapl_red_streak += 1
            else:
                self.aapl_red_streak = 0

            change = aapl_close - previous_aapl_close
            gain = max(change, Decimal(0))
            loss = max(-change, Decimal(0))
            self.aapl_rsi_changes += 1

