class ExactStrategySystemAlgorithm(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        self.symbols = {}
        for ticker in ["SPY", "AAPL", "IBM", "BAC", "AIG"]:
            self.symbols[ticker] = self.AddEquity(
                ticker, Resolution.Daily
            ).Symbol

        self.spy = self.symbols["SPY"]
        self.aapl = self.symbols["AAPL"]

        self.spy_sma = SimpleMovingAverage(100)
        self.aapl_rsi = RelativeStrengthIndex(
            14, MovingAverageType.Wilders
        )

        self.previous_spy_close = None
        self.previous_spy_sma = None
        self.previous_aapl_close = None
        self.aapl_red_streak = 0

        self.spy_lot_open = False
        self.aapl_lot_open = False
        self.spy_order_pending = False
        self.aapl_order_pending = False

        self.fixed_aapl_purchase = Decimal("20000")

    def OnData(self, data):
        bars = data.Bars

        spy_bar = bars[self.spy] if bars.ContainsKey(self.spy) else None
        aapl_bar = bars[self.aapl] if bars.ContainsKey(self.aapl) else None

        current_spy_sma = None

        if spy_bar is not None:
            self.spy_sma.Update(spy_bar.EndTime, spy_bar.Close)
            if self.spy_sma.IsReady:
                current_spy_sma = self.spy_sma.Current.Value

        if aapl_bar is not None:
            if self.previous_aapl_close is not None:
                if aapl_bar.Close < self.previous_aapl_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0

            self.aapl_rsi.Update(aapl_bar.EndTime, aapl_bar.Close)

        all_bars_present = all(
            bars.ContainsKey(symbol) for symbol in self.symbols.values()
        )

        if all_bars_present:
            self.EvaluateStrategyA(spy_bar, current_spy_sma)
            self.EvaluateStrategyB(aapl_bar)

        if spy_bar is not None:
            self.previous_spy_close = spy_bar.Close
            if current_spy_sma is not None:
                self.previous_spy_sma = current_spy_sma

        if aapl_bar is not None:
            self.previous_aapl_close = aapl_bar.Close

    def EvaluateStrategyA(self, bar, current_sma):
        if (
            current_sma is None
            or self.previous_spy_close is None
            or self.previous_spy_sma is None
            or self.spy_order_pending
        ):
            return

        crosses_above = (
            self.previous_spy_close <= self.previous_spy_sma
            and bar.Close > current_sma
        )
        crosses_below = (
            self.previous_spy_close >= self.previous_spy_sma
            and bar.Close < current_sma
        )

        if self.spy_lot_open:
            if crosses_below:
                quantity = self.Portfolio[self.spy].Quantity
                if quantity != 0:
                    self.spy_order_pending = True
                    self.MarketOrder(
                        self.spy, -quantity, tag="StrategyA-Sell"
                    )
                else:
                    self.spy_lot_open = False
            return

        if crosses_above:
            quantity = self.CalculateOrderQuantity(self.spy, 0.40)
            if quantity > 0:
                self.spy_order_pending = True
                self.MarketOrder(
                    self.spy, quantity, tag="StrategyA-Buy"
                )

    def EvaluateStrategyB(self, bar):
        if not self.aapl_rsi.IsReady or self.aapl_order_pending:
            return

        if self.aapl_lot_open:
            if self.aapl_rsi.Current.Value > 60:
                quantity = self.Portfolio[self.aapl].Quantity
                if quantity != 0:
                    self.aapl_order_pending = True
                    self.MarketOrder(
                        self.aapl, -quantity, tag="StrategyB-Sell"
                    )
                else:
                    self.aapl_lot_open = False
            return

        if self.aapl_red_streak >= 3:
            if self.Portfolio.Cash >= self.fixed_aapl_purchase:
                quantity = int(self.fixed_aapl_purchase / bar.Close)
                if quantity > 0:
                    self.aapl_order_pending = True
                    self.MarketOrder(
                        self.aapl, quantity, tag="StrategyB-Buy"
                    )

    def OnOrderEvent(self, order_event):
        if order_event.Status not in [
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid
        ]:
            return

        order = self.Transactions.GetOrderById(order_event.OrderId)
        if order is None:
            return

        if order.Tag == "StrategyA-Buy":
            self.spy_order_pending = False
            if order_event.Status == OrderStatus.Filled:
                self.spy_lot_open = True

        elif order.Tag == "StrategyA-Sell":
            self.spy_order_pending = False
            if order_event.Status == OrderStatus.Filled:
                self.spy_lot_open = (
                    self.Portfolio[self.spy].Quantity != 0
                )

        elif order.Tag == "StrategyB-Buy":
            self.aapl_order_pending = False
            if order_event.Status == OrderStatus.Filled:
                self.aapl_lot_open = True

        elif order.Tag == "StrategyB-Sell":
            self.aapl_order_pending = False
            if order_event.Status == OrderStatus.Filled:
                self.aapl_lot_open = (
                    self.Portfolio[self.aapl].Quantity != 0
                )

