class IndependentParallelStrategies(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        self.symbols = {}
        for ticker in ["SPY", "AAPL", "IBM", "BAC", "AIG"]:
            self.symbols[ticker] = self.AddEquity(
                ticker, Resolution.Daily
            ).Symbol

        self.spy = self.symbols["SPY"]
        self.aapl = self.symbols["AAPL"]

        self.spy_closes = deque(maxlen=101)

        self.aapl_previous_close = None
        self.aapl_red_streak = 0

        self.rsi_period = 14
        self.rsi_previous_close = None
        self.rsi_initial_gains = []
        self.rsi_initial_losses = []
        self.rsi_average_gain = None
        self.rsi_average_loss = None
        self.aapl_rsi = None

        self.spy_lot = 0
        self.aapl_lot = 0

    def OnData(self, data):
        bars = data.Bars

        if bars.ContainsKey(self.spy):
            self.spy_closes.append(float(bars[self.spy].Close))

        if bars.ContainsKey(self.aapl):
            aapl_close = float(bars[self.aapl].Close)
            self.UpdateAaplRedStreak(aapl_close)
            self.UpdateAaplRsi(aapl_close)

        if any(not bars.ContainsKey(symbol) for symbol in self.symbols.values()):
            return

        spy_close = float(bars[self.spy].Close)
        aapl_close = float(bars[self.aapl].Close)

        spy_crossed_above = False
        spy_crossed_below = False

        if len(self.spy_closes) == 101:
            yesterday_close = self.spy_closes[-2]
            yesterday_sma = sum(list(self.spy_closes)[:100]) / 100.0
            today_sma = sum(list(self.spy_closes)[-100:]) / 100.0

            spy_crossed_above = (
                yesterday_close <= yesterday_sma and spy_close > today_sma
            )
            spy_crossed_below = (
                yesterday_close >= yesterday_sma and spy_close < today_sma
            )

        # Evaluate sells before buys.
        if self.spy_lot > 0 and spy_crossed_below:
            self.MarketOrder(self.spy, -self.spy_lot)
            self.spy_lot = 0

        if (
            self.aapl_lot > 0
            and self.aapl_rsi is not None
            and self.aapl_rsi > 60.0
        ):
            self.MarketOrder(self.aapl, -self.aapl_lot)
            self.aapl_lot = 0

        if self.spy_lot == 0 and spy_crossed_above:
            target_value = float(self.Portfolio.TotalPortfolioValue) * 0.40
            quantity = int(math.floor(target_value / spy_close))
            if quantity > 0:
                self.MarketOrder(self.spy, quantity)
                self.spy_lot = quantity

        if self.aapl_lot == 0 and self.aapl_red_streak >= 3:
            available_cash = self.Portfolio.CashBook["USD"].Amount
            if available_cash >= Decimal("20000"):
                quantity = int(math.floor(20000.0 / aapl_close))
                if quantity > 0:
                    self.MarketOrder(self.aapl, quantity)
                    self.aapl_lot = quantity

    def UpdateAaplRedStreak(self, close):
        if self.aapl_previous_close is not None:
            if close < self.aapl_previous_close:
                self.aapl_red_streak += 1
            else:
                self.aapl_red_streak = 0

        self.aapl_previous_close = close

    def UpdateAaplRsi(self, close):
        if self.rsi_previous_close is None:
            self.rsi_previous_close = close
            return

        change = close - self.rsi_previous_close
        gain = max(change, 0.0)
        loss = max(-change, 0.0)

        if self.rsi_average_gain is None:
            self.rsi_initial_gains.append(gain)
            self.rsi_initial_losses.append(loss)

            if len(self.rsi_initial_gains) == self.rsi_period:
                self.rsi_average_gain = (
                    sum(self.rsi_initial_gains) / self.rsi_period
                )
                self.rsi_average_loss = (
                    sum(self.rsi_initial_losses) / self.rsi_period
                )
                self.aapl_rsi = self.CalculateRsi()
        else:
            self.rsi_average_gain = (
                self.rsi_average_gain * (self.rsi_period - 1) + gain
            ) / self.rsi_period
            self.rsi_average_loss = (
                self.rsi_average_loss * (self.rsi_period - 1) + loss
            ) / self.rsi_period
            self.aapl_rsi = self.CalculateRsi()

        self.rsi_previous_close = close

    def CalculateRsi(self):
        if self.rsi_average_loss == 0:
            if self.rsi_average_gain == 0:
                return 50.0
            return 100.0

        relative_strength = self.rsi_average_gain / self.rsi_average_loss
        return 100.0 - (100.0 / (1.0 + relative_strength))

