            if aapl_close < self.aapl_previous_close:
                self.aapl_red_streak += 1
            else:
                self.aapl_red_streak = 0

        self.UpdateAaplRsi(aapl_close)

        spy_crosses_above = False
        spy_crosses_below = False
        if (
            spy_sma is not None
            and self.spy_previous_ready_close is not None
            and self.spy_previous_ready_sma is not None
        ):
            spy_crosses_above = (
                self.spy_previous_ready_close <= self.spy_previous_ready_sma
                and spy_close > spy_sma
            )
            spy_crosses_below = (
                self.spy_previous_ready_close >= self.spy_previous_ready_sma
                and spy_close < spy_sma
            )

        # Evaluate sells before buys.
        if self.strategy_a_shares > 0 and spy_crosses_below:
            self.MarketOrder(
                self.symbols["SPY"], -self.strategy_a_shares
            )
            self.strategy_a_shares = 0

        if (
            self.strategy_b_shares > 0
            and self.aapl_rsi is not None
            and self.aapl_rsi > 60.0
        ):
            self.MarketOrder(
                self.symbols["AAPL"], -self.strategy_b_shares
            )
            self.strategy_b_shares = 0

        if self.strategy_a_shares == 0 and spy_crosses_above:
            quantity = self.CalculateOrderQuantity(
                self.symbols["SPY"], 0.40
            )
            if quantity > 0:
                self.MarketOrder(self.symbols["SPY"], quantity)
                self.strategy_a_shares = quantity

        if self.strategy_b_shares == 0 and self.aapl_red_streak >= 3:
            if float(self.Portfolio.Cash) >= 20_000.0:
                quantity = math.floor(20_000.0 / aapl_close)
                if quantity > 0:
                    self.MarketOrder(self.symbols["AAPL"], quantity)
                    self.strategy_b_shares = quantity

        if spy_sma is not None:
            self.spy_previous_ready_close = spy_close
            self.spy_previous_ready_sma = spy_sma

        self.aapl_previous_close = aapl_close

    def UpdateAaplRsi(self, close):
        if self.aapl_average_gain is None:
            self.aapl_rsi_closes.append(close)

            if len(self.aapl_rsi_closes) < 15:
                return

            closes = list(self.aapl_rsi_closes)
            gains = 0.0
            losses = 0.0

            for index in range(1, 15):
                change = closes[index] - closes[index - 1]
                if change > 0:
                    gains += change
                elif change < 0:
                    losses -= change

            self.aapl_average_gain = gains / 14.0
            self.aapl_average_loss = losses / 14.0
        else:
            change = close - self.aapl_previous_close
            gain = max(change, 0.0)
            loss = max(-change, 0.0)

            self.aapl_average_gain = (
                self.aapl_average_gain * 13.0 + gain
            ) / 14.0
            self.aapl_average_loss = (
                self.aapl_average_loss * 13.0 + loss
            ) / 14.0

        if self.aapl_average_loss == 0.0:
            self.aapl_rsi = (
                0.0 if self.aapl_average_gain == 0.0 else 100.0
            )
        else:
            relative_strength = (
                self.aapl_average_gain / self.aapl_average_loss
            )
            self.aapl_rsi = 100.0 - (
                100.0 / (1.0 + relative_strength)
            )
