        if any(symbol not in data.Bars for symbol in self.symbols):
            return

        # Strategy A: evaluate its sell before its buy.
        if self.strategy_a_shares > 0:
            if spy_crosses_below and not self.strategy_a_pending:
                self.strategy_a_pending = True
                self.MarketOrder(
                    self.spy,
                    -self.strategy_a_shares,
                    tag="StrategyA"
                )
        elif not self.strategy_a_pending:
            if spy_crosses_above:
                quantity = self.CalculateOrderQuantity(self.spy, 0.40)
                if quantity > 0:
                    self.strategy_a_pending = True
                    self.MarketOrder(self.spy, quantity, tag="StrategyA")

        # Strategy B: evaluate its sell before its buy.
        if self.strategy_b_shares > 0:
            if (
                self.aapl_rsi.IsReady
                and self.aapl_rsi.Current.Value > 60
                and not self.strategy_b_pending
            ):
                self.strategy_b_pending = True
                self.MarketOrder(
                    self.aapl,
                    -self.strategy_b_shares,
                    tag="StrategyB"
                )
        elif not self.strategy_b_pending:
