                    quantity = floor(cash_required / aapl_bar.Close)
                    if quantity > 0:
                        self.strategy_b_pending = True
                        self.MarketOrder(
                            self.aapl,
                            quantity,
                            tag="StrategyB"
                        )

    def OnOrderEvent(self, order_event):
        order = self.Transactions.GetOrderById(order_event.OrderId)
        if order is None:
            return

        if order_event.Status in [OrderStatus.PartiallyFilled, OrderStatus.Filled]:
            if order.Tag == "StrategyA":
                self.strategy_a_shares += order_event.FillQuantity
                self.strategy_a_shares = max(0, self.strategy_a_shares)
            elif order.Tag == "StrategyB":
                self.strategy_b_shares += order_event.FillQuantity
                self.strategy_b_shares = max(0, self.strategy_b_shares)

        if order_event.Status in [
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid
        ]:
            if order.Tag == "StrategyA":
                self.strategy_a_pending = False
            elif order.Tag == "StrategyB":
                self.strategy_b_pending = False

